UT: [C002] shutdownChildProcess guarantees child death — precondition input, postcondition assertion, invariant predicate
```ts
// Precondition input: a live child (EventEmitter) with a kill recorder.
const proc = new EventEmitter() as any;
proc.exitCode = null;
const kills: Array<string | undefined> = [];
proc.kill = (sig?: any) => { kills.push(sig); };
proc.stdin = { end: () => {} };
// Postcondition assertion: SIGTERM sent, then child exits; grace-expiry forces SIGKILL.
const promise = shutdownChildProcess(proc, 2000);
setImmediate(() => proc.emit("exit", 0, null));
await promise;
assert.deepStrictEqual(kills, [undefined]); // SIGTERM first
const stuck = new EventEmitter() as any;
stuck.exitCode = null;
const stuckKills: Array<string | undefined> = [];
stuck.kill = (sig?: any) => { stuckKills.push(sig); };
stuck.stdin = { end: () => {} };
await shutdownChildProcess(stuck, 20); // grace expires, child never exits
assert.deepStrictEqual(stuckKills, [undefined, "SIGKILL"]);
// Invariant predicate: never throws; no-op on an already-dead process.
const throwing = new EventEmitter() as any;
throwing.exitCode = null;
throwing.kill = () => { throw new Error("kill error"); };
throwing.stdin = { end: () => { throw new Error("end error"); } };
await assert.doesNotReject(shutdownChildProcess(throwing, 10));
const dead = { exitCode: 0, kill: () => { throw new Error("no kill"); }, stdin: { end: () => { throw new Error("no end"); } } } as any;
await assert.doesNotReject(shutdownChildProcess(dead, 10));
```

