const digest = (p) => createHash("sha256").update(fs.readFileSync(p)).digest("hex");
const countFor = (text) => text.split("\n").filter((l) => l.includes("[::TICKET::] " + KEY)).length;

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "px208-interposed-"));
const file = path.join(dir, "interposed.js");
