```js
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync } from 'node:fs';
const digestTree = (dir) => {
  const out = {};
  for (const name of readdirSync(dir).sort()) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) Object.assign(out, digestTree(full));
    else out[full] = createHash('sha256').update(readFileSync(full)).digest('hex');
  }
  return out;
};
test('C001 invariant: capture and check never alter a target byte', () => {
  const before = digestTree(TREE_FIXTURES);
  captureBaselines({ fixtureRoots: [TREE_FIXTURES, ALLOCATE_FIXTURES], baselinePath: tmpBaseline });
