  checkBaselines({ baselinePath: tmpBaseline, fixtureRoots: [TREE_FIXTURES, ALLOCATE_FIXTURES] });
  assert.deepEqual(digestTree(TREE_FIXTURES), before, 'check must not write into the fixture tree');
});
