```js
test('C002 invariant: a strong relation folds, and an undeterminable assessment is unknown', () => {
  const implementationEvidence = makeEvidence('ev-impl-31', { file: 'src/authz.rs', line: 42 }, []);
  const testEvidence = makeEvidence('ev-test-77', { file: 'src/authz.rs', line: 42 }, [
    { relation: 'same_syntax_span', target: 'ev-impl-31', confidence: 'high', basis: ['src/authz.rs:42-46'] },
  ]);
  const readmeEvidence = makeEvidence('ev-readme-12', { file: 'README.md', line: 3 }, [
    { relation: 'same_commit', target: 'ev-impl-31', confidence: 'medium', basis: ['git:a1b2c3d'] },
  ]);

  // strong and medium both collapse; the count is components, never records.
  assert.equal(countIndependentSupport([implementationEvidence, testEvidence]), 1);
  assert.equal(countIndependentSupport([implementationEvidence, readmeEvidence]), 1);

  // Three artefacts, one derivation: the independent count is strictly less.
  const folded = computeIndependence([implementationEvidence, testEvidence, readmeEvidence]);
  assert.ok(
    folded.independentCount < folded.evidence.length,
    'the independent group count is strictly less than the raw evidence count',
  );

  // What the text cannot settle is recorded as unknown, never defaulted to independent.
  assert.equal(computeIndependence([implementationEvidence, readmeEvidence], { root: null }).evidence[1].independence_assessment, 'unknown');
});
