UT: [C002 invariant -> filesystem invariant predicate] nothing outside RFC-SEED.md and the manifest changes on disk, asserted by inspecting the filesystem before and after
```js
import { mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createHash } from 'node:crypto';

const fingerprint = (root) => {
  const entries = [];
  const visit = (abs, rel) => {
    for (const dirent of readdirSync(abs, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const relPath = rel ? `${rel}/${dirent.name}` : dirent.name;
      if (dirent.isDirectory()) { entries.push(`dir ${relPath}`); visit(join(abs, dirent.name), relPath); }
      else { entries.push(`file ${relPath} ${createHash('sha256').update(readFileSync(join(abs, dirent.name))).digest('hex')}`); }
    }
  };
  visit(root, '');
  return entries;
};

const root = mkdtempSync(join(tmpdir(), 'reverse-invariant-'));
try {
  mkdirSync(join(root, 'src/api'), { recursive: true });
  writeFileSync(join(root, 'src/api/mod.rs'), 'pub fn call() {}\n');
  const before = fingerprint(root);
  const reversed = runReverseAllocate({ manifestDir: root, manifest, decisions, mode: 'reverse' });
  const after = fingerprint(root);
  const created = after.filter((line) => !before.includes(line));
  assert.ok(created.every((line) => line.includes('RFC-SEED.md') || line.includes('WORKSPACIFY-ALLOCATE-MANIFEST.json')));
  // Every pre-existing entry survives with identical bytes.
  assert.deepEqual(before.filter((line) => line.startsWith('file ')), after.filter((line) => before.includes(line) && line.startsWith('file ')));
} finally {
  rmSync(root, { recursive: true, force: true });
}
```

